from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-19' and end_date = '2025-05-19')
and start_date = '2025-05-19' and end_date = '2025-05-19'

/* cppi::d67e6cc8ff6f2c502a9f259900b7de92c1ea11819f69656b6f9284af65255470 */
